function highlight(n){document.querySelectorAll('.frame').forEach((el,i)=>{el.classList.toggle('active',i===n);el.setAttribute('aria-pressed',String(i===n))})}
function timeline(){document.querySelectorAll('.move').forEach(b=>b.classList.toggle('accent',b.dataset.move===selected));$('frames').innerHTML='';for(let i=0;i<6;i++){let b=document.createElement('button');b.className='frame';b.setAttribute('aria-label','Fotogramma '+(i+1)+' '+labels[selected][i]);let img=poseImage(0,selected,i);b.innerHTML=`<img src="${img?.src||''}" alt=""><span>0${i+1} / ${labels[selected][i]}</span>`;b.onclick=()=>{if(!ready)return;scrub=i;fighters.forEach(f=>{f.active=false;f.type=selected;f.frame=i});$('loop').checked=false;highlight(i);message('Fotogramma 0'+(i+1)+' · '+labels[selected][i].toLowerCase())};$('frames').append(b)}highlight(0)}
function select(type){selected=type;scrub=null;timeline()}
function hit(a,b,damage){const target=fighters[b],attacker=fighters[a];if(Math.abs(attacker.x-target.x)>(attacker.type==='kick'?270:245)){message('Colpo a vuoto · Avvicinati');return}if(target.active&&target.type==='dodge'&&target.frame>=2&&target.frame<=3){message('Schivata riuscita · Nessun danno');return}if(target.active&&target.type==='jump'&&target.frame>=2&&target.frame<=3){message('Colpo evitato in salto');return}const block=target.active&&target.type==='block'&&target.frame>=2&&target.frame<=3;target.hp=Math.max(0,target.hp-(block?0:damage));fx.push({x:(attacker.x+target.x)/2,y:330,t:.25,blocked:block});message(block?'Parata riuscita · Nessun danno':'Colpo a segno · −'+damage+' vita');if(!target.hp)message('Bersaglio esaurito · Ripristina per riprovare')}
function step(dt){if(!ready||scrub!==null)return;let scaled=dt*Number($('speed').value);
 // Update both poses before resolving impacts, for simultaneous defensive inputs.
 fighters.forEach((f,i)=>{let mv=i?Number(!!keys.arrowright)-Number(!!keys.arrowleft):Number(!!keys.d)-Number(!!keys.a);if(!f.active){f.x+=mv*190*scaled;f.walk=mv?f.walk+scaled:0;f.x=Math.max(155,Math.min(1045,f.x))}if(f.active){f.t+=scaled;f.frame=frameAt(f.type,f.t);if(f.type==='block'&&(i?keys.arrowdown:keys.s)&&f.frame>=3){f.t=timings.block.slice(0,3).reduce((a,b)=>a+b,0);f.frame=3;f.blocking=true}if(f.t>=timings[f.type].reduce((a,b)=>a+b,0)){f.active=false;f.frame=0;f.t=0;f.blocking=false;if(comboQueue&&comboQueue.id===i)comboQueue.next()}}});
 fighters.forEach((f,i)=>{if(f.active&&['punch','kick'].includes(f.type)&&f.frame>=3&&!f.hit){f.hit=true;hit(i,1-i,f.type==='kick'?15:10)}});
 let[a,b]=fighters;if(Math.abs(a.x-b.x)<170){let mid=(a.x+b.x)/2;a.x=mid-85;b.x=mid+85}
 if($('partner').checked){botTimer-=scaled;if(botTimer<=0){botTimer=1.7;action(1,'punch')}}
 if($('loop').checked&&!fighters.some(f=>f.active))compare();fx.forEach(e=>e.t-=dt);fx=fx.filter(e=>e.t>0);highlight(fighters.find(f=>f.active&&f.type===selected)?.frame??0)}
function background(){let g=ctx.createLinearGradient(0,0,0,600);g.addColorStop(0,'#e7dfd4');g.addColorStop(1,'#c8b7a0');ctx.fillStyle=g;ctx.fillRect(0,0,1200,600);ctx.strokeStyle='#bda99155';ctx.lineWidth=2;for(let x=80;x<1200;x+=208){ctx.strokeRect(x,105,180,355);ctx.beginPath();ctx.moveTo(x+90,105);ctx.lineTo(x+90,460);ctx.stroke()}ctx.fillStyle='#d7c8b5';ctx.fillRect(0,460,1200,140);ctx.fillStyle='#b8a68f';ctx.fillRect(0,460,1200,5);ctx.strokeStyle='#baa78e66';for(let x=-1000;x<2500;x+=180){ctx.beginPath();ctx.moveTo(600+(x-600)*.25,465);ctx.lineTo(x,600);ctx.stroke()}for(let y of[485,520,570]){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1200,y);ctx.stroke()}ctx.font='100px Georgia';ctx.textAlign='center';ctx.fillStyle='#aa8e7520';ctx.fillText('ECLIPSE',600,260)}
function draw(){background();if(!ready)return;fighters.forEach((f,i)=>{let frame=scrub??f.frame,type=scrub!==null?selected:f.active?f.type:'punch',img=poseImage(i,type,frame);if(!f.active&&scrub===null&&f.walk>0&&Math.floor(f.walk*8)%2)img=images.study[i][1];ctx.save();ctx.translate(f.x,557);ctx.scale(i?-1:1,1);let punchAsset=img.src.includes('/punch/');let width=punchAsset?270:324,height=punchAsset?405:459;if(type==='kick'&&f.active&&frame>0&&frame<5){let phase=frame===3?1:frame===2||frame===4?.6:.15;ctx.globalAlpha=phase;ctx.drawImage(img,-width/2,-height,width,height);ctx.globalAlpha=1-phase;ctx.drawImage(images.punch[i][0],-135,-405,270,405);ctx.globalAlpha=1}else ctx.drawImage(img,-width/2,-height,width,height);ctx.restore();$('hp'+i).style.width=f.hp+'%'});fx.forEach(e=>{ctx.strokeStyle=e.blocked?'#416775':'#a43e2d';ctx.lineWidth=3;ctx.globalAlpha=Math.min(1,e.t*6);for(let i=0;i<8;i++){let a=i*Math.PI/4,r=(.25-e.t)*180;ctx.beginPath();ctx.moveTo(e.x+Math.cos(a)*r,e.y+Math.sin(a)*r);ctx.lineTo(e.x+Math.cos(a)*(r+12),e.y+Math.sin(a)*(r+12));ctx.stroke()}ctx.globalAlpha=1})}
$('punch0').onclick=()=>action(0);$('punch1').onclick=()=>action(1);$('both').onclick=compare;$('reset').onclick=reset;$('loop').onchange=()=>{if($('loop').checked)compare()};document.querySelectorAll('.move').forEach(b=>b.onclick=()=>select(b.dataset.move));
const mapping={u:[0,'punch'],i:[0,'kick'],q:[0,'dodge'],w:[0,'jump'],s:[0,'block'],j:[1,'punch'],k:[1,'kick'],l:[1,'dodge'],arrowup:[1,'jump'],arrowdown:[1,'block'],o:[0,'airkick'],m:[1,'airkick']};
function keyDown(k){if(!keys[k]&&mapping[k])action(...mapping[k]);keys[k]=true}
window.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;let k=e.key.toLowerCase();if(mapping[k]||['a','d','arrowleft','arrowright',' '].includes(k))e.preventDefault();keyDown(k);if(k===' '&&!e.repeat)compare()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keyDown(b.dataset.key)};for(let evt of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(evt,()=>keys[b.dataset.key]=false)});
reset();
const loads=[];
for(const type of ['punch','dodge','jump','block','study']){images[type]=[[],[]];for(let r=0;r<2;r++)for(let n=0;n<6;n++)loads.push(new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>{images[type][r][n]=im;resolve()};im.onerror=reject;im.src=`assets-alpha/${type}/${r}-${n}.png`}))}
