const simCanvas=$('simStage'),simCtx=simCanvas?.getContext('2d');let sim={run:false,hp:[160,160],energy:[0,0],round:1,score:[0,0],x:[170,470],state:['idle','idle'],type:['punch','punch'],t:[0,0],cool:[0,0],hit:[false,false],last:0,flash:0,attacker:0,log:'SIMULAZIONE FERMA'};
function simReset(){sim={run:false,hp:[160,160],energy:[0,0],round:1,score:[0,0],x:[170,470],state:['idle','idle'],type:['punch','punch'],t:[0,0],cool:[0,0],hit:[false,false],last:performance.now(),flash:0,attacker:0,log:'SIMULAZIONE FERMA'};if($('simInfo'))$('simInfo').textContent='Premi “Avvia simulazione” per iniziare';simDraw()}
function simStart(){if(sim.score[0]>=2||sim.score[1]>=2)simReset();sim.run=true;sim.last=performance.now();sim.log='I combattenti entrano nell’arena';if($('simInfo'))$('simInfo').textContent='Partita simulata · Round '+sim.round}
function simChoose(i){const d=Math.abs(sim.x[0]-sim.x[1]);if(d>155){sim.state[i]='walk';sim.type[i]='punch';return}const special=sim.energy[i]>=100&&Math.random()<.18;const choices=special?['special']:['punch','kick','dodge','jump','block','airkick'];sim.type[i]=choices[Math.floor(Math.random()*choices.length)];sim.state[i]='action';sim.t[i]=0;sim.hit[i]=false;sim.log=(i?'Ninja':'Demone')+' usa '+(sim.type[i]==='special'?(i?'Lama d’ombra':'Fiamma oscura'):sim.type[i]);}
function simDamage(i){const o=1-i,d=Math.abs(sim.x[i]-sim.x[o]);if(d>205||sim.hit[i])return;if(['dodge','jump','block'].includes(sim.type[o])){sim.log=(o?'Ninja':'Demone')+' difende il colpo';return}const special=sim.type[i]==='special',damage=special?34:(sim.type[i]==='kick'||sim.type[i]==='airkick'?7:5);sim.hp[o]=Math.max(0,sim.hp[o]-damage);sim.hit[i]=true;sim.flash=performance.now();sim.energy[i]=Math.min(100,sim.energy[i]+(special?0:12));sim.log=(i?'Ninja':'Demone')+' colpisce · -'+damage+' vita'+(special?' · SPECIALE':'');}
function simUpdate(dt){if(!sim.run)return;for(let i=0;i<2;i++){sim.energy[i]=Math.min(100,sim.energy[i]+dt*.65);sim.cool[i]-=dt;sim.t[i]+=dt;if(sim.state[i]==='walk'){const dir=sim.x[i]<sim.x[1]?1:-1;sim.x[i]+=dir*55*dt;if(Math.abs(sim.x[0]-sim.x[1])<170)sim.state[i]='idle'}else if(sim.state[i]==='action'){const total=sim.type[i]==='special'?1.2:timings[sim.type[i]].reduce((a,b)=>a+b,0);if(sim.t[i]>.28)simDamage(i);if(sim.t[i]>total){sim.state[i]='idle';sim.t[i]=0;sim.cool[i]=.35}}else if(sim.cool[i]<=0){simChoose(i);sim.cool[i]=.45}sim.x[i]=Math.max(95,Math.min(545,sim.x[i]))}if(sim.hp[0]<=0||sim.hp[1]<=0){const winner=sim.hp[0]>0?0:1;sim.score[winner]++;if(sim.score[winner]>=2){sim.run=false;sim.log=(winner?'Ninja':'Demone')+' vince la partita simulata'}else{sim.round++;sim.hp=[160,160];sim.energy=[0,0];sim.x=[170,470];sim.state=['idle','idle'];sim.cool=[.5,.8];sim.log=(winner?'Demone':'Ninja')+' vince il round · Round '+sim.round}}if($('simInfo'))$('simInfo').textContent=sim.log+' · '+sim.score[0]+' — '+sim.score[1]}
function simDraw(){if(!simCtx)return;const w=simCanvas.width,now=performance.now(),pulse=Math.max(0,1-(now-sim.flash)/300);simCtx.clearRect(0,0,w,simCanvas.height);simCtx.fillStyle='#101516';simCtx.fillRect(0,0,w,simCanvas.height);simCtx.fillStyle='#222b2b';simCtx.fillRect(0,205,w,55);simCtx.fillStyle='#ddb167';simCtx.fillRect(22,22,220*sim.hp[0]/160,10);simCtx.fillStyle='#6c9ca3';simCtx.fillRect(w-242,22,220*sim.hp[1]/160,10);simCtx.fillStyle='#d96f45';simCtx.fillRect(22,36,220*sim.energy[0]/100,6);simCtx.fillStyle='#7db8c2';simCtx.fillRect(w-242,36,220*sim.energy[1]/100,6);simCtx.fillStyle='#eadfcf';simCtx.font='bold 11px sans-serif';simCtx.fillText('DEMONE '+Math.round(sim.hp[0])+' HP',22,17);simCtx.textAlign='right';simCtx.fillText(Math.round(sim.hp[1])+' HP NINJA',w-22,17);simCtx.textAlign='center';simCtx.font='bold 13px sans-serif';simCtx.fillText('ROUND '+sim.round+'   ·   '+sim.score[0]+' — '+sim.score[1],w/2,30);if(ready){for(let i=0;i<2;i++){const type=sim.state[i]==='action'?(sim.type[i]==='special'?'punch':sim.type[i]):'punch',frame=sim.state[i]==='action'&&type!=='special'?frameAt(type,sim.t[i]):0,img=poseImage(i,type,frame);if(img){simCtx.save();simCtx.translate(sim.x[i],0);simCtx.scale(i?-1:1,1);simCtx.drawImage(img,-75,55,150,225);simCtx.restore()}}}if(pulse){simCtx.fillStyle='#ddb167';simCtx.font='bold 17px sans-serif';simCtx.fillText('IMPATTO!',w/2,105)}if(sim.run&&sim.type.includes('special')){simCtx.fillStyle='#ff613c';simCtx.font='bold 12px sans-serif';simCtx.fillText('ABILITÀ SPECIALE IN CARICA',w/2,125)}simCtx.fillStyle='#ddb167';simCtx.font='11px sans-serif';simCtx.fillText(sim.run?'PARTITA AUTOMATICA · COMBO · SPECIALI · ROUND':sim.log,w/2,258)}
function simTick(ms){const dt=Math.min((ms-sim.last)/1000,.05);sim.last=ms;simUpdate(dt);simDraw();requestAnimationFrame(simTick)}
$('simStart')?.addEventListener('click',simStart);$('simReset')?.addEventListener('click',simReset);simReset();requestAnimationFrame(simTick);

const specialCanvas=$('specialStage'),specialCtx=specialCanvas?.getContext('2d');let special={energy:100,active:false,type:null,t:0,cool:0,last:0};
function specialReset(){special={energy:100,active:false,type:null,t:0,cool:0,last:performance.now()};if($('specialInfo'))$('specialInfo').textContent='Scegli una tecnica speciale per provarla.';specialDraw()}
function specialUse(type){if(special.active||special.energy<50){if($('specialInfo'))$('specialInfo').textContent=special.energy<50?'Energia insufficiente · attendi la ricarica':'Tecnica già in corso';return}special.type=type;special.active=true;special.t=0;special.energy-=50;if($('specialInfo'))$('specialInfo').textContent=type==='demon'?'Demone: Fiamma oscura · attacco a distanza':'Ninja: Lama d’ombra · scatto e colpo';}
function specialUpdate(dt){special.energy=Math.min(100,special.energy+dt*7);if(special.active){special.t+=dt;if(special.t>1.35)special.active=false}if($('specialEnergy'))$('specialEnergy').style.width=special.energy+'%';if($('specialEnergyValue'))$('specialEnergyValue').textContent=Math.round(special.energy)+'%'}
function specialDraw(){if(!specialCtx)return;const w=specialCanvas.width,h=specialCanvas.height,now=performance.now();specialCtx.clearRect(0,0,w,h);specialCtx.fillStyle='#0e1214';specialCtx.fillRect(0,0,w,h);specialCtx.fillStyle='#222b2b';specialCtx.fillRect(0,205,w,55);specialCtx.fillStyle='#ddb167';specialCtx.font='bold 12px sans-serif';specialCtx.fillText('DEMONE',35,24);specialCtx.textAlign='right';specialCtx.fillStyle='#7db8c2';specialCtx.fillText('NINJA',w-35,24);specialCtx.textAlign='center';if(ready){const a=images.punch[0][0],b=images.punch[1][0];if(a)specialCtx.drawImage(a,70,35,125,190);if(b)specialCtx.save(),specialCtx.translate(w-70,0),specialCtx.scale(-1,1),specialCtx.drawImage(b,-195,35,125,190),specialCtx.restore()}if(special.active){const p=Math.min(1,special.t/.45),fade=Math.max(0,1-(special.t-1)/.35);if(special.type==='demon'){specialCtx.globalAlpha=fade;specialCtx.fillStyle='#ff5b36';specialCtx.shadowColor='#ff3b1f';specialCtx.shadowBlur=25;specialCtx.beginPath();specialCtx.arc(220+p*230,130,18+10*Math.sin(now/70),0,Math.PI*2);specialCtx.fill();specialCtx.globalAlpha=1;specialCtx.shadowBlur=0}else{specialCtx.globalAlpha=fade;specialCtx.strokeStyle='#8de8ff';specialCtx.shadowColor='#6eeaff';specialCtx.shadowBlur=18;specialCtx.lineWidth=12;specialCtx.beginPath();specialCtx.moveTo(w-190-p*210,95);specialCtx.lineTo(w-255-p*210,165);specialCtx.stroke();specialCtx.globalAlpha=1;specialCtx.shadowBlur=0}}specialCtx.fillStyle='#ddb167';specialCtx.font='11px sans-serif';specialCtx.fillText(special.active?(special.type==='demon'?'FIAMMA OSCURA · IMPATTO':'LAMA D’OMBRA · IMPATTO'):'PRONTA · COSTO 50 ENERGIA',w/2,245)}
